package com.carebridge.backend.partner.service;
import com.carebridge.backend.partner.dto.request.PerformanceFilter;import com.carebridge.backend.partner.dto.response.PartnerPerformanceResponse;import com.carebridge.backend.partner.exception.PartnerException;import com.carebridge.backend.partner.repository.*;import java.time.Instant;import java.util.*;import java.util.UUID;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor public class PartnerPerformanceServiceImpl implements PartnerPerformanceService{private final PartnerOrganizationRepository orgRepo;private final PartnerServiceRepository serviceRepo;private final SponsoredCampaignRepository campaignRepo;private final PartnerExpertLinkRepository linkRepo;@Override @Transactional(readOnly=true)public PartnerPerformanceResponse getPerformance(PerformanceFilter filter,UUID actorId){
 if(!filter.isValid())throw PartnerException.invalidPerformanceRange();var org=orgRepo.findByRepresentativeUserId(actorId).orElseThrow(PartnerException::performanceOrganizationNotFound);Map<String,Long> services=toMap(serviceRepo.countByStatus(org.getId()));Map<String,Long> campaigns=toMap(campaignRepo.countByStatus(org.getId(),filter.from(),filter.to()));long links=linkRepo.countByPartnerIdAndStatus(org.getId(),"ACTIVE");return new PartnerPerformanceResponse(services,campaigns,links,filter.from(),filter.to(),Instant.now());}
 private Map<String,Long> toMap(List<Object[]> rows){Map<String,Long> result=new LinkedHashMap<>();for(Object[] row:rows)result.put(String.valueOf(row[0]),((Number)row[1]).longValue());return result;}}
